export function openingKey(op) {
  return `${op.eco} ${op.name}`;
}

/** Copy of an opening node ({eco, name, idea}) with Spanish text when `lang` is 'es'. */
export function localizeOpening(op, lang) {
  if (!op || lang !== 'es') return op;
  const k = openingKey(op);
  return { ...op, name: NAMES_ES[k] || op.name, idea: IDEAS_ES[k] || op.idea };
}
